import BASICWasmRunner
import Foundation

/// The frameworks a program BASICStudio runs may `IMPORT` (BASIC-45), and
/// what the compiler and the runner need of each.
///
/// Studio contains ActiveUI and TUIKit, so a program may import them; it may
/// import nothing Studio does not contain. The rest of this target is
/// generated by `basicc framework-map` — R4's shims for every member, and
/// the entries that call them by name — and must not be edited by hand.
public enum BASICFrameworkMap {
    /// One framework a program may import.
    public struct Framework: Sendable {
        /// The module name a program imports: `ActiveUI`.
        public let module: String
        /// Its symbol graph, which `IMPORT` reads (R4.1).
        public let symbolGraph: URL
        /// The symbols its binary exports, which decide what can be called.
        public let exported: URL
    }

    /// The frameworks Studio contains, from this target's resources.
    public static var frameworks: [Framework] {
        ["ActiveUI", "TUIKit"].compactMap { module in
            guard let graph = Bundle.module.url(forResource: "\(module).symbols", withExtension: "json", subdirectory: "Resources"),
                  let exported = Bundle.module.url(forResource: module, withExtension: "exported", subdirectory: "Resources")
            else { return nil }
            return Framework(module: module, symbolGraph: graph, exported: exported)
        }
    }

    /// Every shim, by name, for the runner: a module's imports of them are
    /// answered here. With them, retain and release, which a program's
    /// imported objects take as Swift objects do.
    public static var entries: [String: WasmEntryPoint] {
        var all = ActiveUIEntries.merging(TUIKitEntries) { first, _ in first }
        all["swift_retain"] = WasmEntryPoint(arity: 1) { a in
            if let object = UnsafeMutableRawPointer(bitPattern: UInt(a[0])) {
                _ = Unmanaged<AnyObject>.fromOpaque(object).retain()
            }
            return a[0]
        }
        all["swift_release"] = WasmEntryPoint(arity: 1) { a in
            if let object = UnsafeMutableRawPointer(bitPattern: UInt(a[0])) {
                Unmanaged<AnyObject>.fromOpaque(object).release()
            }
            return 0
        }
        return all
    }
}
